(()=>{const enableBulkTranslateBtn=()=>{const AutoMlSubsubsubList=jQuery(".automl_wpml_subsubsub"),AutoMlBulkTranslateBtn=jQuery(".automl-wpml-bulk-translate-btn");if(AutoMlSubsubsubList.length){const $defaultSubsubsub=jQuery("ul.subsubsub:not(.automl_wpml_subsubsub_list)");$defaultSubsubsub.length&&($defaultSubsubsub.after(AutoMlSubsubsubList),AutoMlSubsubsubList.show())}const appendButton=btn=>{if(!btn.length||btn.length<0)return;const $defaultFilter=jQuery(".actions:not(.bulkactions)"),$bulkAction=jQuery(".actions.bulkactions");$defaultFilter.length?($defaultFilter.each((function(){const clone=btn.clone(!0);jQuery(this).append(clone),clone.show()})),btn.remove()):$bulkAction.length&&$bulkAction.each((function(){const clone=btn.clone(!0);jQuery(this).after(clone),clone.show()}))};appendButton(AutoMlBulkTranslateBtn)};window.addEventListener("load",()=>{enableBulkTranslateBtn()})})();